import json, urllib.request, urllib.parse, re, sys
from datetime import date, timedelta, datetime

BASE='http://127.0.0.1:8123'
today=date(2026,7,31)  # supplied current UTC date
this_monday=today-timedelta(days=today.weekday())
week_end=this_monday-timedelta(days=1)
week_start=week_end-timedelta(days=6)
comp_end=week_start-timedelta(days=1)
comp_start=comp_end-timedelta(days=6)

date_re=re.compile(r'^\d{4}-\d{2}-\d{2}$')

def fetch(start,end):
    url=f'{BASE}/orders?'+urllib.parse.urlencode({'start':start.isoformat(),'end':end.isoformat()})
    try:
        with urllib.request.urlopen(url, timeout=15) as r:
            if not (200 <= r.status < 300):
                raise RuntimeError(f'GET returned HTTP {r.status}')
            raw=r.read()
    except Exception as e:
        raise RuntimeError(f'Failed to fetch {start} through {end}: {e}')
    try:
        data=json.loads(raw)
    except Exception as e:
        raise RuntimeError(f'Invalid JSON for {start} through {end}: {e}')
    if not isinstance(data,list):
        raise RuntimeError(f'Response for {start} through {end} is not a JSON list')
    used=[]
    for i,o in enumerate(data):
        # Orders with an absent/invalid date cannot be established as in-range and are not used.
        if not isinstance(o,dict):
            continue
        ds=o.get('date')
        if not isinstance(ds,str) or not date_re.fullmatch(ds):
            continue
        try: od=date.fromisoformat(ds)
        except ValueError: continue
        if not (start <= od <= end):
            continue
        missing=[k for k in ('order_id','date','region','units','unit_price_cents') if k not in o]
        if missing:
            raise RuntimeError(f'Order index {i} in {start}..{end} missing fields: {missing}')
        if o['order_id'] is None:
            raise RuntimeError(f'Order index {i} has invalid order_id')
        if not isinstance(o['region'],str):
            raise RuntimeError(f'Order index {i} has non-string region')
        if not isinstance(o['units'],int) or isinstance(o['units'],bool):
            raise RuntimeError(f'Order index {i} has non-integer units')
        if not isinstance(o['unit_price_cents'],int) or isinstance(o['unit_price_cents'],bool):
            raise RuntimeError(f'Order index {i} has non-integer unit_price_cents')
        used.append(o)
    return used

def totals(orders):
    units=sum(o['units'] for o in orders)
    by={}
    for o in orders:
        rev=o['units']*o['unit_price_cents']
        by[o['region']]=by.get(o['region'],0)+rev
    return units,sum(by.values()),by

try:
    current=fetch(week_start,week_end)
    previous=fetch(comp_start,comp_end)
    total_units,current_rev,by_region=totals(current)
    _,previous_rev,_=totals(previous)
    if previous_rev == 0:
        raise RuntimeError('Comparison-week revenue is zero; refusing to POST report')
    report={
        'week_start':week_start.isoformat(),
        'week_end':week_end.isoformat(),
        'total_units':total_units,
        'total_revenue_cents':current_rev,
        'revenue_by_region_cents':by_region,
        'wow_revenue_change_pct':round((current_rev-previous_rev)/previous_rev*100,2),
    }
    body=json.dumps(report,separators=(',',':')).encode()
    req=urllib.request.Request(f'{BASE}/report',data=body,method='POST',headers={'Content-Type':'application/json'})
    try:
        with urllib.request.urlopen(req,timeout=15) as r:
            response=r.read().decode(errors='replace')
            if not (200 <= r.status < 300):
                raise RuntimeError(f'POST returned HTTP {r.status}: {response}')
            print(json.dumps({'delivered':True,'http_status':r.status,'report':report},indent=2,sort_keys=True))
    except urllib.error.HTTPError as e:
        detail=e.read().decode(errors='replace')
        raise RuntimeError(f'POST returned HTTP {e.code}: {detail}')
except Exception as e:
    print(f'Weekly orders report failed: {e}',file=sys.stderr)
    sys.exit(1)
